package io.busystack.busydata;

import io.busystack.busydata.protocol.*;
import io.busystack.busydata.schema.*;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class ExactNativeValuesIT {
    @TempDir Path root;
    @Test void postgresSpecialNumericsBitsBooleanAndEndOfDayKeepNativeIdentity()throws Exception {
        try(var f=new EngineFixture(root,"POSTGRESQL")){
            var session=f.open();String table=session.adapter.table("busydata","public","exact_native_values");
            f.execute(session,"CREATE TYPE exact_status AS ENUM ('new','active',''); CREATE TABLE "+table+"(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,n INTEGER,v NUMERIC,b BIT(1),flag BOOLEAN,t TIMETZ,s exact_status); INSERT INTO "+table+"(n,v,b,flag,t,s) VALUES(1,'NaN',B'1',true,'24:00:00+02','new'),(2,'Infinity',B'0',false,'00:00:00+00','active'),(3,'-Infinity',B'1',true,'12:00:00+00','')");
            f.warm(session,"exact_native_values");new Explorer(f.metadata).refreshFragment(session,"busydata","public","exact_status",ObjectKind.TYPE);
            var source=f.results.get(f.execute(session,"SELECT id,n,v,b,flag,t,s FROM "+table+" ORDER BY id").info().getResults(0).getResultId());
            for(int index=0;index<3;index++)assertEquals(new String[]{"NaN","Infinity","-Infinity"}[index],source.read(index).getValues(2).getEngineValue().getText());
            assertEquals("1",source.read(0).getValues(3).getEngineValue().getText());assertTrue(source.read(0).getValues(4).hasBoolean());assertTrue(source.read(0).getValues(4).getBoolean());assertFalse(source.read(1).getValues(4).getBoolean());
            assertTrue(io.busystack.busydata.results.Values.text(source.read(0).getValues(5)).startsWith("24:00:00"));
            var planner=new ChangePlanner(f.safety,f.results,f.metadata.metadataPlatform());
            var request=ChangeRequest.newBuilder().setSessionId(session.id).setCatalog("busydata").setSchema("public").setTable("exact_native_values").setResultId(source.id)
                .addChanges(StagedChange.newBuilder().setKind(ChangeKind.UPDATE).setSourceRow(0).putValues(2,Assignments.value(EditingIT.integer(9))).putValues(6,Assignments.value(Value.newBuilder().setText("24:00:00+03:00").build())).putValues(7,Assignments.value(Value.newBuilder().setText("active").build()))).build();
            EditingIT.apply(planner,f.jobs,session,request);
            try(var statement=session.connection.createStatement();var rows=statement.executeQuery("SELECT n,v::text,b::text,flag,t::text,s::text FROM "+table+" WHERE id=1")){
                assertTrue(rows.next());assertEquals(9,rows.getInt(1));assertEquals("NaN",rows.getString(2));assertEquals("1",rows.getString(3));assertTrue(rows.getBoolean(4));assertEquals("24:00:00+03",rows.getString(5));assertEquals("active",rows.getString(6));
            }
            var clone=planner.cloneRow(session,CloneRowRequest.newBuilder().setSessionId(session.id).setResultId(source.id).setCatalog("busydata").setSchema("public").setTable("exact_native_values").setSourceRow(0).build());
            EditingIT.apply(planner,f.jobs,session,request.toBuilder().clearChanges().addChanges(clone).build());
            try(var statement=session.connection.createStatement();var rows=statement.executeQuery("SELECT v::text,b::text,flag,t::text,s::text FROM "+table+" WHERE id=4")){
                assertTrue(rows.next());assertEquals("NaN",rows.getString(1));assertEquals("1",rows.getString(2));assertTrue(rows.getBoolean(3));assertEquals("24:00:00+02",rows.getString(4));assertEquals("new",rows.getString(5));
            }
        }
    }
}
